S = "Hakeem Force Academy"
QS = [
(S, "What is the 15th night of Shaban called?", ["Shab-e-Qadr", "Shab-e-Barat", "Shab-e-Meraj", "Laylat al-Raghaib"], 1, "The night of the 15th of Shaban is known as Shab-e-Barat (night of forgiveness or record).", "Shaban is the eighth month of the Islamic calendar and comes just before Ramadan.", 1),
(S, "Which is the 3rd surah of the Holy Quran?", ["Al-Baqarah", "An-Nisa", "Ali Imran", "Al-Maidah"], 2, "The order is Al-Fatiha, Al-Baqarah, Ali Imran, so the third is Ali Imran.", "Surah Ali Imran has 200 verses and is a Madani surah.", 1),
(S, "In the commonly taught Pakistani order of the five pillars of Islam (Kalima, Salah, Roza, Zakat, Hajj), which is the 4th pillar?", ["Hajj", "Fasting", "Zakat", "Salah"], 2, "In this order the pillars run Shahada, Salah, Fasting, Zakat, Hajj, so the fourth is Zakat.", "Sources differ: the hadith in Sahih Bukhari lists Hajj before fasting, which makes Hajj fourth.", 1),
(S, "An acute angle is how large compared with a right angle?", ["Equal to a right angle", "Smaller than a right angle", "Larger than a right angle", "Exactly twice a right angle"], 1, "A right angle is 90 degrees and an acute angle is any angle between 0 and 90 degrees, so it is smaller.", "An angle larger than 90 and smaller than 180 degrees is called obtuse.", 1),
(S, "On which date is American Independence Day celebrated?", ["4 July", "14 July", "4 June", "25 December"], 0, "The US Declaration of Independence was adopted on 4 July 1776, and that day is celebrated as Independence Day.", "The Declaration was mainly drafted by Thomas Jefferson.", 1),
(S, "What is the antonym of 'ally'?", ["Friend", "Partner", "Enemy", "Helper"], 2, "An ally is a supporter or friend, and its opposite is an enemy or foe.", "The word ally comes from the Latin alligare, meaning to bind to.", 1),
(S, "What is the antonym of 'cease'?", ["Stop", "Continue", "End", "Finish"], 1, "To cease means to stop, so its opposite is to continue.", "Cease is also often used in the phrase ceasefire.", 1),
(S, "What is the antonym of 'chum'?", ["Friend", "Pal", "Enemy", "Mate"], 2, "A chum is a close friend, and the opposite is an enemy.", "Chum is an informal word and a synonym of buddy.", 1),
(S, "What is the antonym of 'climb'?", ["Ascend", "Descend", "Rise", "Mount"], 1, "To climb is to go up, and the opposite is to descend (go down).", "Descend comes from the Latin descendere.", 1),
(S, "What is the antonym of 'expansion'?", ["Growth", "Enlargement", "Contraction", "Extension"], 2, "Expansion means growing larger, and its opposite is contraction (becoming smaller).", "In economics the opposite phases are expansion and contraction (recession).", 1),
(S, "What is the antonym of 'proceed'?", ["Advance", "Continue", "Halt", "Progress"], 2, "To proceed is to go forward, and the opposite is to halt or stop.", "Proceed is a synonym of advance, continue and progress.", 1),
(S, "Which line is the boundary between Pakistani Punjab and Indian Punjab?", ["Durand Line", "Radcliffe Line", "McMahon Line", "Line of Control"], 1, "The 1947 boundary award of Sir Cyril Radcliffe divided Punjab and Bengal between Pakistan and India.", "The Durand Line separates Pakistan and Afghanistan, and the McMahon Line is in the India-China area.", 2),
(S, "Which name is given to the Battle of Khandaq (the Trench) in the Quran?", ["Battle of Badr", "Battle of Uhud", "Battle of Ahzab", "Battle of Hunain"], 2, "The Battle of Khandaq (5 AH) is also called Ahzab (the Confederates), after the allied tribes who besieged Madinah.", "The trench was dug on the advice of Salman al-Farsi.", 2),
(S, "What is the base of the natural logarithm?", ["10", "2", "e (about 2.718)", "pi (about 3.14)"], 2, "The natural logarithm ln x is the logarithm to base e, where e is approximately 2.71828.", "Common logarithms use base 10, and computer science often uses base 2.", 1),
(S, "What is the value of tan(-x)?", ["tan x", "-tan x", "1 / tan x", "-cot x"], 1, "Tangent is an odd function, because sin(-x) = -sin x and cos(-x) = cos x, so tan(-x) = -tan x.", "Cosine is an even function, so cos(-x) = cos x.", 1),
(S, "Which is the biggest continent in the world by area?", ["Africa", "North America", "Asia", "Europe"], 2, "Asia covers about 44.6 million square kilometres, which is the largest of all continents.", "Asia is also the most populous continent.", 1),
(S, "In Islam, which is the biggest sin?", ["Theft", "Shirk (associating partners with Allah)", "Lying", "Disobeying parents"], 1, "The Quran and Hadith describe shirk as the greatest sin, and Allah does not forgive it unless a person repents.", "The Quran (Surah An-Nisa 4:48) says that Allah does not forgive shirk but forgives lesser sins.", 1),
(S, "What is the capital of Balochistan?", ["Gwadar", "Turbat", "Quetta", "Khuzdar"], 2, "Quetta is the provincial capital and largest city of Balochistan.", "Quetta is known as the Fruit Garden of Pakistan.", 2),
(S, "What is the capital of Bangladesh?", ["Chittagong", "Dhaka", "Sylhet", "Khulna"], 1, "Dhaka is the capital and largest city of Bangladesh.", "Bangladesh became independent from Pakistan in 1971.", 1),
(S, "What is the political capital of Burundi?", ["Bujumbura", "Gitega", "Kigali", "Kampala"], 1, "Burundi moved its political capital from Bujumbura to Gitega in 2019.", "Bujumbura remains the economic capital and the largest city, and was the capital before 2019.", 1),
(S, "What is the capital of Canada?", ["Toronto", "Montreal", "Vancouver", "Ottawa"], 3, "Ottawa is the capital of Canada, although Toronto is the largest city.", "Ottawa lies on the Ottawa River in the province of Ontario.", 1),
(S, "What is the capital of Germany?", ["Munich", "Frankfurt", "Hamburg", "Berlin"], 3, "Berlin is the capital of Germany.", "Bonn was the capital of West Germany before reunification in 1990.", 1),
(S, "What is the capital of Peru?", ["Bogota", "Lima", "Quito", "Santiago"], 1, "Lima is the capital and largest city of Peru.", "Bogota is the capital of Colombia, Quito of Ecuador and Santiago of Chile.", 1),
(S, "What is the capital of Australia?", ["Sydney", "Melbourne", "Canberra", "Perth"], 2, "Canberra is the capital of Australia, chosen as a compromise between Sydney and Melbourne.", "Sydney is Australia's largest city.", 1),
(S, "What is the capital of Azerbaijan?", ["Baku", "Tbilisi", "Yerevan", "Ganja"], 0, "Baku is the capital of Azerbaijan, on the Caspian Sea.", "Tbilisi is the capital of Georgia and Yerevan of Armenia.", 1),
(S, "What is the capital of Uganda?", ["Nairobi", "Kampala", "Kigali", "Dodoma"], 1, "Kampala is the capital of Uganda.", "Entebbe, near Kampala, hosts Uganda's main international airport.", 1),
(S, "Which city was the capital of the ancient Gandhara civilization in Pakistani textbooks?", ["Mohenjo-daro", "Harappa", "Taxila", "Multan"], 2, "Taxila (Takshashila) is the capital of Gandhara most often given in Pakistani textbooks.", "Sources differ: Pushkalavati and later Peshawar (Purushapura) also served as Gandhara capitals.", 1),
]
